class ErrorBoundary extends React.Component {
  state = { error: null };

  // Render phase: return the new state, must be pure
  static getDerivedStateFromError(error) {
    return { error };
  }

  // Commit phase: side effects such as logging belong here
  componentDidCatch(error, errorInfo) {
    logToService(error, errorInfo.componentStack);
  }

  render() {
    if (this.state.error) {
      return this.props.fallback ?? <p>Something went wrong.</p>;
    }
    return this.props.children;
  }
}

import { ErrorBoundary } from "react-error-boundary";

<ErrorBoundary
  FallbackComponent={ErrorFallback}
  onReset={() => refetch()}
>
  <Dashboard />
</ErrorBoundary>

function SaveButton() {
  const [error, setError] = useState(null);

  async function handleClick() {
    try {
      await save();
    } catch (err) {
      setError(err);
    }
  }

  if (error) return <p role="alert">Save failed.</p>;
  return <button onClick={handleClick}>Save</button>;
}

const [error, setError] = useState(null);
if (error) throw error;   // now a boundary can catch it

